describe('ToolRegistry schema compilation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#6
  it('rejects an invalid static schema at registration', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {name: 'broken', description: 'Invalid schema', inputSchema: {type: 'invalid'}},
        async () => 'unreachable'
      )
    ).toThrow(/broken/);
