// specs/hal-engine-tool-input-validation/spec.md#2
it('rejects missing required input', async () => {
  const registry = new ToolRegistry();
  let calls = 0;
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async () => {
      calls += 1;
      return 'forecast';
    }
  );
  const response = await registry.execute('weather', {});
  expect({result: response.result, calls}).toEqual({
    result: expect.stringMatching(/location.*required|required.*location/i),
    calls: 0,
  });
});

// specs/hal-engine-tool-input-validation/spec.md#9
it('validates each current dynamic schema', async () => {
  const registry = new ToolRegistry();
  let schema = {type: 'object', required: ['first']};
  registry.register(
    () => ({name: 'dynamic', description: 'Dynamic', inputSchema: schema}),
    async () => 'accepted'
  );
  const first = await registry.execute('dynamic', {});
  schema = {type: 'object', required: ['second']};
  const second = await registry.execute('dynamic', {});
  expect([first.result, second.result]).toEqual([expect.stringContaining('first'), expect.stringContaining('second')]);
});
